// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(uint256 amount) public {
        // Keep the deposit admissible (>= MinDeposit) and within a sane range.
        amount = bound(amount, c.MinDeposit(), 100 ether);

        address actor = address(this);
        vm.deal(actor, amount + 1 ether);

        uint256 before = c.balances(actor);

        vm.prank(actor);
        c.Deposit{value: amount}();

        uint256 afterBal = c.balances(actor);

        assertEq(afterBal, before + amount);
    }
}
